// BE-16: confere a assinatura HMAC-SHA256 que o backend do Flui envia em
// X-Flui-Signature sobre "<X-Flui-Timestamp>.<corpo>" e recusa pedidos com mais
// de 5 minutos (reenvio). Sem o segredo configurado, nenhum pedido passa.
const crypto = require('crypto');

let secret;
try {
  secret = $env.WEBHOOK_SECRET; // n8n self-hosted: variável de ambiente
} catch (e) {
  secret = undefined; // acesso a variáveis bloqueado nesta instância
}
// n8n Cloud não tem variáveis de ambiente: troque o texto abaixo pelo segredo.
if (!secret) secret = 'COLE_AQUI_O_WEBHOOK_SECRET';
if (secret === 'COLE_AQUI_O_WEBHOOK_SECRET') {
  throw new Error('WEBHOOK_SECRET não configurado no n8n');
}

const STAGE_LABELS = {
  inicial: 'Primeiro Contato',
  cadastro: 'Cadastro',
  analise_credito: 'Análise de Crédito',
  credito_aprovado: 'Crédito Aprovado',
  analise_juridica: 'Análise Jurídica',
  juridico_aprovado: 'Jurídico Aprovado',
  cartorio: 'Cartório',
  assinatura: 'Assinatura',
  cliente_inativo: 'Inativo',
  credito_recusado: 'Crédito Recusado',
  processo_pendencia: 'Pendência',
};

return $input.all().map((item) => {
  const { headers, body } = item.json;
  const ts = String(headers['x-flui-timestamp'] || '');
  const got = String(headers['x-flui-signature'] || '');
  // o backend envia JSON compacto; reserializar o corpo dá os mesmos bytes
  const expected =
    'sha256=' +
    crypto.createHmac('sha256', secret).update(ts + '.' + JSON.stringify(body)).digest('hex');
  const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
  if (
    !fresh ||
    got.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected))
  ) {
    throw new Error('Webhook sem assinatura válida do Flui');
  }
  return {
    json: {
      ...body,
      fromLabel: STAGE_LABELS[body.fromStage] || body.fromStage || '',
      toLabel: STAGE_LABELS[body.toStage] || body.toStage || '',
    },
  };
});
